function updateBars(){ui('hpText',Math.ceil(player.hp));ui('manaText',Math.floor(player.mana));ui('levelText','LV '+String(player.level).padStart(2,'0'));ui('essenceText',player.essence);ui('herbText',player.herbs);ui('oreText',player.ore);document.getElementById('hpBar').style.width=100*player.hp/player.maxHp+'%';document.getElementById('manaBar').style.width=100*player.mana/player.maxMana+'%';document.getElementById('xpBar').style.width=(player.xp%100)+'%';ui('repText',rep>=3?'TRUSTED':rep>0?'WELCOMED':rep<0?'WARY':'NEUTRAL');document.querySelector('.rep-track i').style.width=clamp(40+rep*10,8,90)+'%';ui('shardCheck',player.shards>=3?'✓':'');document.getElementById('shardCheck').classList.toggle('done',player.shards>=3);ui('objectiveText',player.shards>=3?(sentinelAlive?'Return to the Wayfarer camp. Something stirs beneath the roots.':'The echo-shards are yours. The forest remembers.'):'Find the three echo-shards. '+player.shards+' of 3 recovered.');ui('questTitle',player.shards>=3?'The forest remembers':'A stranger in the roots');ui('questCopy',player.shards>=3?'Three voices have answered. Return to the old camp and learn what the Veil wants.':'The last thing you remember is rain on city glass. Now a voice stirs beneath the old forest.');ui('className',player.class.toUpperCase())}
function gainXP(n){player.xp+=n;if(player.xp>=100){player.xp-=100;player.level++;player.maxHp+=12;player.hp=player.maxHp;player.maxMana+=8;player.mana=player.maxMana;say('RENOWN RISES · LEVEL '+player.level)}updateBars()}
function drawNode(n,s){const pulse=.65+Math.sin(elapsed*3+n.x)*.18;ctx.save();ctx.translate(s.x,s.y);ctx.globalAlpha=pulse;if(n.type==='shard'){ctx.shadowColor='#dbbd73';ctx.shadowBlur=18;ctx.fillStyle='#ddc27d';ctx.beginPath();ctx.moveTo(0,-18*s.scale);ctx.lineTo(8*s.scale,-3*s.scale);ctx.lineTo(0,5*s.scale);ctx.lineTo(-8*s.scale,-3*s.scale);ctx.closePath();ctx.fill();ctx.shadowBlur=0}else if(n.type==='herb'){ctx.strokeStyle='#9bb77f';ctx.lineWidth=2;for(let i=-1;i<=1;i++){ctx.beginPath();ctx.moveTo(0,0);ctx.lineTo(i*7*s.scale,-12*s.scale);ctx.stroke();ctx.fillStyle='#9eb77b';ctx.beginPath();ctx.ellipse(i*6*s.scale,-10*s.scale,3*s.scale,5*s.scale,i*.5,0,TAU);ctx.fill()}}else if(n.type==='ore'){ctx.fillStyle='#75817a';ctx.beginPath();ctx.moveTo(-10*s.scale,0);ctx.lineTo(-7*s.scale,-12*s.scale);ctx.lineTo(2*s.scale,-18*s.scale);ctx.lineTo(11*s.scale,-10*s.scale);ctx.lineTo(10*s.scale,0);ctx.closePath();ctx.fill();ctx.fillStyle='#bac0a5';ctx.fillRect(-2*s.scale,-12*s.scale,3*s.scale,5*s.scale)}else{ctx.fillStyle='#b9a875';ctx.beginPath();ctx.ellipse(0,-2*s.scale,13*s.scale,5*s.scale,0,0,TAU);ctx.fill();ctx.fillStyle='#8c7655';ctx.fillRect(-3*s.scale,-15*s.scale,6*s.scale,13*s.scale);ctx.fillStyle='#d5bd79';ctx.beginPath();ctx.arc(0,-17*s.scale,5*s.scale,0,TAU);ctx.fill()}ctx.restore()}
function drawActor(a,s,isPlayer=false){ctx.save();ctx.translate(s.x,s.y);let sc=s.scale;if(isPlayer){ctx.fillStyle='rgba(0,0,0,.35)';ctx.beginPath();ctx.ellipse(0,0,12*sc,5*sc,0,0,TAU);ctx.fill();ctx.fillStyle=player.invuln>0&&Math.floor(elapsed*18)%2?'#f0dfab':'#263a3a';ctx.beginPath();ctx.moveTo(-8*sc,-4*sc);ctx.lineTo(-7*sc,-17*sc);ctx.lineTo(0,-24*sc);ctx.lineTo(7*sc,-17*sc);ctx.lineTo(8*sc,-4*sc);ctx.closePath();ctx.fill();ctx.fillStyle='#d6b780';ctx.beginPath();ctx.arc(0,-25*sc,5*sc,0,TAU);ctx.fill();ctx.strokeStyle='#d9c67f';ctx.lineWidth=2*sc;ctx.beginPath();ctx.moveTo(5*sc,-13*sc);ctx.lineTo((5+player.facing.y*8)*sc,(-20-player.facing.x*4)*sc);ctx.stroke();if(player.attackCd>.48){ctx.strokeStyle='rgba(239,211,141,.65)';ctx.lineWidth=2*sc;ctx.beginPath();ctx.arc(0,-13*sc,25*sc,-1.2,1.2);ctx.stroke()}}else{ctx.fillStyle='rgba(0,0,0,.3)';ctx.beginPath();ctx.ellipse(0,0,12*sc,5*sc,0,0,TAU);ctx.fill();ctx.fillStyle=a.hit>0?'#ead9b0':a.kind==='moth'?'#9b8d73':a.kind==='hollow'?'#778170':a.kind==='wolf'?'#596354':'#78574a';ctx.beginPath();ctx.ellipse(0,-12*sc,11*sc,8*sc,0,0,TAU);ctx.fill();ctx.fillStyle='#d7bd77';ctx.beginPath();ctx.arc(4*sc,-14*sc,1.5*sc,0,TAU);ctx.fill();if(a.hp<a.maxHp){ctx.fillStyle='#17201a';ctx.fillRect(-12*sc,-28*sc,24*sc,3*sc);ctx.fillStyle='#bd755f';ctx.fillRect(-12*sc,-28*sc,24*sc*a.hp/a.maxHp,3*sc)}}ctx.restore()}
function drawProps(){const things=[];for(const p of props){if(Math.abs(p.x-player.x)>18||Math.abs(p.y-player.y)>18)continue;things.push({x:p.x,y:p.y,draw:s=>p.type==='tree'||p.type==='pine'?treeShape(s,p.type,p.seed):p.type==='rock'?drawRock(s,p.seed):p.type==='dead'?treeShape(s,'pine',0):null})}for(const n of nodes)if(n.active)things.push({x:n.x,y:n.y,draw:s=>drawNode(n,s)});for(const e of enemies)if(e.alive)things.push({x:e.x,y:e.y,draw:s=>drawActor(e,s)});things.push({x:player.x,y:player.y,draw:s=>drawActor(player,s,true)});things.sort((a,b)=>a.x+a.y-b.x-b.y);for(const o of things)o.draw(worldToScreen(o.x,o.y))}
function drawAtmosphere(){let night=clamp((Math.sin((dayTime/24)*TAU-Math.PI/2)+.18)*-.45+.15,0,.48);if(night){ctx.fillStyle=`rgba(11,19,31,${night})`;ctx.fillRect(0,0,W,H)}if(weather==='Mist'){let g=ctx.createLinearGradient(0,H*.35,0,H);g.addColorStop(0,'rgba(188,196,171,.02)');g.addColorStop(1,'rgba(188,196,171,.19)');ctx.fillStyle=g;ctx.fillRect(0,0,W,H)}if(weather==='Rain'){ctx.strokeStyle='rgba(190,205,195,.25)';ctx.lineWidth=1;for(let i=0;i<55;i++){let x=(i*173+elapsed*180)%W,y=(i*97+elapsed*290)%H;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x-5,y+13);ctx.stroke()}}}
function drawMini(){const r=mini.getBoundingClientRect(),w=r.width,h=r.height;if(!w||!h)return;mx.clearRect(0,0,w,h);mx.fillStyle='#263329';mx.fillRect(0,0,w,h);for(let y=0;y<WORLD;y+=2)for(let x=0;x<WORLD;x+=2){mx.fillStyle=terrainColor(x,y);mx.globalAlpha=.6;mx.fillRect(x/WORLD*w,y/WORLD*h,2*w/WORLD+1,2*h/WORLD+1)}mx.globalAlpha=1;for(const n of nodes)if(n.active){mx.fillStyle=n.type==='shard'?'#d8bd76':n.type==='npc'?'#9cb68c':'#8c9977';mx.fillRect(n.x/WORLD*w-1,n.y/WORLD*h-1,3,3)}for(const e of enemies)if(e.alive){mx.fillStyle='#c37c67';mx.fillRect(e.x/WORLD*w-1,e.y/WORLD*h-1,3,3)}mx.fillStyle='#f0d47f';mx.beginPath();mx.arc(player.x/WORLD*w,player.y/WORLD*h,3,0,TAU);mx.fill();mx.strokeStyle='rgba(237,218,156,.5)';mx.strokeRect((player.x-5)/WORLD*w,(player.y-5)/WORLD*h,10/WORLD*w,10/WORLD*h)}
function render(){ctx.clearRect(0,0,W,H);const g=ctx.createLinearGradient(0,0,0,H);g.addColorStop(0,'#1b2822');g.addColorStop(1,'#111a17');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);ctx.save();if(shake>0)ctx.translate((Math.random()-.5)*shake,(Math.random()-.5)*shake);drawGround();drawProps();for(const p of particles){const s=worldToScreen(p.x,p.y);ctx.globalAlpha=clamp(p.life,0,1);ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(s.x,s.y,2.2*s.scale,0,TAU);ctx.fill()}ctx.globalAlpha=1;ctx.restore();drawAtmosphere();drawMini()}

