function openDialog(title,intro,body='',footer='ESC TO RETURN'){menuOpen=true;const d=document.getElementById('dialog');d.innerHTML=`<div class="dialog-top"><div><div class="panel-label">AETHELGARD · THE UNMOORED</div><h2>${title}</h2><p class="intro">${intro}</p></div><button class="close" data-close>×</button></div>${body}<div class="dialog-footer"><span>${footer}</span><span>THE VEIL REMEMBERS</span></div>`;document.getElementById('drawer').classList.add('open')}
function closeDialog(){menuOpen=false;document.getElementById('drawer').classList.remove('open')}
function characterMenu(){openDialog('The vessel','A soul displaced between worlds. Your choices leave a mark.',`<div class="choices"><button class="choice ${player.class==='Spellblade'?'active':''}" data-class="Spellblade"><span class="symbol">⚔</span><h3>Spellblade</h3><p>Balanced steel and ember. A reliable path through the unknown.</p></button><button class="choice ${player.class==='Warden'?'active':''}" data-class="Warden"><span class="symbol">⌖</span><h3>Warden</h3><p>Hardier and deliberate. A little more vigor, a little less mana.</p></button><button class="choice ${player.class==='Arcanist'?'active':''}" data-class="Arcanist"><span class="symbol">✧</span><h3>Arcanist</h3><p>Master of the Veil. Greater mana and a stronger ember.</p></button></div><div class="action-list"><div class="action-row"><div><strong>Wayfarer's satchel</strong><small>Essence ${player.essence} · Moonwort ${player.herbs} · Iron ${player.ore}</small></div><span class="gem">✦</span></div><div class="action-row"><div><strong>Echo-shards</strong><small>${player.shards} of 3 fragments recovered</small></div><span class="gem">◇</span></div></div>`)}
function mapMenu(){openDialog('The known world','A rough field chart, drawn from half-remembered roads.',`<div style="height:min(45vh,340px);position:relative;background:#263329;border:1px solid var(--line);overflow:hidden"><canvas id="bigmap" style="position:absolute;inset:0;width:100%;height:100%"></canvas></div><div class="action-list" style="margin-top:12px"><div class="action-row"><div><strong>Vesperhold</strong><small>North · a city beyond the boughs</small></div><span>◇</span></div><div class="action-row"><div><strong>Moonfall / Cinder March</strong><small>East · shards answer across the frontier</small></div><span>◇</span></div></div>`);const c=document.getElementById('bigmap'),b=c.getBoundingClientRect(),q=c.getContext('2d');c.width=b.width*devicePixelRatio;c.height=b.height*devicePixelRatio;q.scale(devicePixelRatio,devicePixelRatio);for(let y=0;y<WORLD;y++)for(let x=0;x<WORLD;x++){q.fillStyle=terrainColor(x,y);q.fillRect(x/WORLD*b.width,y/WORLD*b.height,b.width/WORLD+1,b.height/WORLD+1)}for(const n of nodes)if(n.active){q.fillStyle=n.type==='shard'?'#e4c57c':'#afbd95';q.beginPath();q.arc(n.x/WORLD*b.width,n.y/WORLD*b.height,4,0,TAU);q.fill()}q.fillStyle='#ffe18a';q.beginPath();q.arc(player.x/WORLD*b.width,player.y/WORLD*b.height,5,0,TAU);q.fill()}
function campDialog(){const reward=player.shards>=3&&!altarAwake;let actions=`<div class="action-list">${reward?'<div class="action-row"><div><strong>The buried voice</strong><small>Three echoes hum beneath the roots.</small></div><button class="action-btn" data-do="awaken">Listen</button></div>':''}<div class="action-row"><div><strong>Rest at the waystone</strong><small>Restore vigor and mana. The road can wait.</small></div><button class="action-btn" data-do="rest">Rest</button></div><div class="action-row"><div><strong>Trade gathered goods</strong><small>3 herbs → 1 healing draught (restores 35 vigor)</small></div><button class="action-btn" data-do="potion" ${player.herbs<3?'disabled':''}>Brew</button></div></div>`;openDialog('Wayfarer camp','A small fire burns beneath a canopy of ancient roots. The coals give off no smoke.',actions,'ECHO-SHARDS '+player.shards+'/3')}
function talk(n){if(n.name==='Lady Ysabet'){openDialog('Lady Ysabet · Vesperhold','The magistrate watches the forest from behind a veil of silver chain.',`<div class="action-list"><div class="action-row"><div><strong>Ask about the Veil</strong><small>“It is a wound, not a road. The old clans know its edges.”</small></div><span>✧</span></div><div class="action-row"><div><strong>Ask about the shards</strong><small>“Three echoes. One voice. Take care what answers.”</small></div><span>◇</span></div><div class="action-row"><div><strong>Offer a moonwort</strong><small>Gain the city's favor; requires 1 herb.</small></div><button class="action-btn" data-do="gift" ${player.herbs<1?'disabled':''}>Offer</button></div></div>`)}else if(n.name==='Alpha Runa'){openDialog('Alpha Runa · Thornbound','A grey wolf speaks without moving her jaw. “The forest has noticed you.”',`<div class="action-list"><div class="action-row"><div><strong>Ask for a blessing</strong><small>Spend 2 essence for a permanent 10 vigor.</small></div><button class="action-btn" data-do="bless" ${player.essence<2?'disabled':''}>Ask</button></div><div class="action-row"><div><strong>Promise to protect the glade</strong><small>The Thornbound remember deeds, not words.</small></div><span>✧</span></div></div>`)} }
function nearest(){let found=null,best=1.65;for(const n of nodes)if(n.active){let d=dist(player,n);if(d<best){best=d;found={kind:'node',item:n,d}}}for(const e of enemies)if(e.alive){let d=dist(player,e);if(d<best){best=d;found={kind:'enemy',item:e,d}}}return found}
function interact(){const hit=nearest();if(!hit){say('Nothing answers nearby.');return}if(hit.kind==='enemy'){attack();return}const n=hit.item;if(n.type==='shard'){n.active=false;player.shards++;player.essence+=2;gainXP(25);say('ECHO-SHARD FOUND · '+player.shards+'/3');updateBars();return}if(n.type==='herb'||n.type==='ore'){n.active=false;if(n.type==='herb')player.herbs++;else player.ore++;gainXP(5);say(n.type==='herb'?'MOONWORT GATHERED':'IRON ORE GATHERED');updateBars();return}if(n.type==='camp'){campDialog();return}if(n.type==='npc'){talk(n);return}if(n.type==='boss'){if(!sentinelAlive){say('The Ashen Wyrm has fallen.');return}if(player.shards<3){say('A voice from the roots: bring the three echoes.');return}openDialog('Ashen Wyrm','The guardian sleeps among black stone. Three echoes have woken it.',`<div class="action-list"><div class="action-row"><div><strong>Face the guardian</strong><small>Be ready. This is the last trial.</small></div><button class="action-btn" data-do="boss">Begin</button></div></div>`);return}}
function emit(x,y,color,count=9){for(let i=0;i<count;i++){let a=Math.random()*TAU,v=.4+Math.random()*1.8;particles.push({x,y,vx:Math.cos(a)*v,vy:Math.sin(a)*v,life:.5+Math.random()*.55,color})}}
function attack(){if(player.attackCd>0||dead)return;player.attackCd=.62;let target=enemies.filter(e=>e.alive&&dist(player,e)<2.05).sort((a,b)=>dist(player,a)-dist(player,b))[0];if(target){target.hp-=player.class==='Warden'?24:20;target.hit=.15;emit(target.x,target.y,'#e4ce8d',7);shake=3;if(target.hp<=0){target.alive=false;hostileKills++;player.essence+=1;gainXP(18);rep++;say(target.name+' defeated · +1 essence');updateBars()}}else{emit(player.x+player.facing.x*.7,player.y+player.facing.y*.7,'#c7b274',3)}}
function cast(){if(player.spellCd>0||player.mana<12||dead)return;player.mana-=12;player.spellCd=.8;const targets=enemies.filter(e=>e.alive&&dist(player,e)<5.2).sort((a,b)=>dist(player,a)-dist(player,b));let target=targets[0];if(target){target.hp-=player.class==='Arcanist'?40:32;target.hit=.18;emit(target.x,target.y,'#9cc8ce',15);shake=5;if(target.hp<=0){target.alive=false;hostileKills++;player.essence+=1;gainXP(18);rep++;say(target.name+' banished · +1 essence')}}else{let x=player.x+player.facing.x*2,y=player.y+player.facing.y*2;projectiles.push({x,y,vx:player.facing.x*8,vy:player.facing.y*8,life:.55});emit(x,y,'#93c4ce',8)}updateBars()}
function dodge(){if(player.dodge>0||dead)return;player.dodge=.38;player.invuln=.55;let dx=(keys.KeyD||keys.ArrowRight?1:0)-(keys.KeyA||keys.ArrowLeft?1:0),dy=(keys.KeyS||keys.ArrowDown?1:0)-(keys.KeyW||keys.ArrowUp?1:0);let l=Math.hypot(dx,dy)||1;player.x=clamp(player.x+dx/l*1.35,1,WORLD-2);player.y=clamp(player.y+dy/l*1.35,1,WORLD-2);emit(player.x,player.y,'#b4d2c3',9)}
function doAction(a){if(a==='attack')attack();if(a==='spell')cast();if(a==='dodge')dodge();if(a==='interact')interact()}

