function doAction(a){if(menuOpen)return;if(a==='attack')attack();if(a==='spell')cast();if(a==='dodge')dodge();if(a==='interact')interact()}
function blocked(x,y){if(x<.6||y<.6||x>WORLD-.8||y>WORLD-.8)return true;for(const p of props)if((p.type==='tree'||p.type==='pine'||p.type==='rock')&&Math.abs(p.x-x)<.42&&Math.abs(p.y-y)<.42)return true;return false}
function update(dt){elapsed+=dt;dayTime=(dayTime+dt*.018)%24;weatherClock+=dt;shake=Math.max(0,shake-dt*13);if(weatherClock>34){weatherClock=0;weather=['Clear','Mist','Rain'][Math.floor(Math.random()*3)];ui('weatherText',weather);ui('weatherGlyph',weather==='Clear'?'☼':weather==='Mist'?'◌':'☂')}ui('timeText',String(Math.floor(dayTime)).padStart(2,'0')+':'+String(Math.floor((dayTime%1)*60/10)*10).padStart(2,'0'));const z=zone(player.x,player.y);ui('regionTag',z.name);player.attackCd=Math.max(0,player.attackCd-dt);player.spellCd=Math.max(0,player.spellCd-dt);player.dodge=Math.max(0,player.dodge-dt);player.invuln=Math.max(0,player.invuln-dt);player.mana=Math.min(player.maxMana,player.mana+dt*1.35);player.walk+=dt*8;
 let dx=(keys.KeyD||keys.ArrowRight?1:0)-(keys.KeyA||keys.ArrowLeft?1:0),dy=(keys.KeyS||keys.ArrowDown?1:0)-(keys.KeyW||keys.ArrowUp?1:0);for(const b of document.querySelectorAll('[data-move].held')){const v=b.dataset.move;if(v==='up')dy--;if(v==='down')dy++;if(v==='left')dx--;if(v==='right')dx++}let len=Math.hypot(dx,dy);if(len){dx/=len;dy/=len;player.facing={x:dx,y:dy};const speed=player.dodge>0?6.5:3.6,nx=player.x+dx*speed*dt,ny=player.y+dy*speed*dt;if(!blocked(nx,player.y))player.x=nx;if(!blocked(player.x,ny))player.y=ny}
 for(const e of enemies)if(e.alive){e.cd=Math.max(0,e.cd-dt);e.hit=Math.max(0,e.hit-dt);let d=dist(e,player);if(d<9){if(d>1.15){let vx=(player.x-e.x)/d,vy=(player.y-e.y)/d,spd=e.kind==='boss'?1.05:1.35;let nx=e.x+vx*spd*dt,ny=e.y+vy*spd*dt;if(!blocked(nx,e.y))e.x=nx;if(!blocked(e.x,ny))e.y=ny}else if(e.cd<=0&&player.invuln<=0){e.cd=e.kind==='boss'?1.05:1.4;player.hp-=e.kind==='boss'?18:10;shake=7;emit(player.x,player.y,'#bd6658',7);updateBars();if(player.hp<=0){player.hp=0;dead=true;openDialog('The veil closes','The forest folds you into its quiet. Your journey is not over.',`<div class="action-list"><div class="action-row"><div><strong>Return to the wayfarer camp</strong><small>Keep your discoveries. The path remains.</small></div><button class="action-btn" data-do="revive">Rise</button></div></div>`,'THE ROOTS REMEMBER')}}}}
